+		t.Fatalf("create document = %d %v", status, data)
+	}
+	id, err := uuid.Parse(data["id"].(string))
+	if err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() {
+		_, _ = srv.db.Exec(context.Background(), `DELETE FROM documents WHERE id=$1`, id)
+	})
+	return id
+}
